self.addEventListener('message',e=>{if(e.data.type!=='DOWNLOAD')return;e.waitUntil((async()=>{try{const results=await Promise.all(FILES.map(async path=>{const url=new URL(path,self.registration.scope).href;const response=await fetch(url,{cache:'reload'});if(!response.ok)throw new Error('部分檔案未下載完成，請重新嘗試。');return [url,response];}));const cache=await caches.open(CACHE);await Promise.all(results.map(([url,response])=>cache.put(url,response)));e.ports[0].postMessage({ok:true});}catch(err){e.ports[0].postMessage({error:err.message});}})());});
